class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Convert each property list to a set for efficient intersection computation
        sets = [set(prop) for prop in properties]

        # Build adjacency list using Union-Find or BFS/DFS
        # Use Union-Find for efficiency
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                parent[rx] = ry
            elif rank[rx] > rank[ry]:
                parent[ry] = rx
            else:
                parent[ry] = rx
                rank[rx] += 1

        # For each pair, check if intersection size >= k
        for i in range(n):
            for j in range(i + 1, n):
                # Compute intersection size
                inter_size = len(sets[i] & sets[j])
                if inter_size >= k:
                    union(i, j)

        # Count number of unique roots
        roots = set()
        for i in range(n):
            roots.add(find(i))

        return len(roots)
