class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        INF = float('inf')

        def cost(a, b):
            d = abs(ord(a) - ord(b))
            return min(d, 26 - d)

        # dp[i][j][l] = min cost to form palindromic subsequence of length l from s[i..j]
        dp = [[[INF] * (n + 1) for _ in range(n)] for _ in range(n)]

        # Base cases: single characters
        for i in range(n):
            dp[i][i][0] = 0
            dp[i][i][1] = 0

        # For empty substrings (length 0), dp[i][j][0] = 0 already via INF handling, but let's be explicit
        # When i > j, it's an empty substring. We'll handle by not accessing those directly in loops,
        # but for the case where i+1 > j-1, we need dp values for "empty" ranges.
        # Let's create a separate structure or handle carefully.
        # Actually, when length=2, i and j are adjacent. Then i+1=j and j-1=i. So dp[i+1][j-1] becomes dp[j][i] which is invalid (i>j).
        # We need to handle the case where the inner substring is empty.

        # Let's redefine: for i > j, the only valid length is 0 with cost 0.
        # We can create a helper to get dp value, treating i>j as empty.

        def get_dp(i, j, l):
            if i > j:
                if l == 0:
                    return 0
                else:
                    return INF
            return dp[i][j][l]

        # Fill for lengths of substring from 2 to n
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1

                # Option 1: skip s[i]
                for l in range(length + 1):
                    val = get_dp(i + 1, j, l)
                    if val < dp[i][j][l]:
                        dp[i][j][l] = val

                # Option 2: skip s[j]
                for l in range(length + 1):
                    val = get_dp(i, j - 1, l)
                    if val < dp[i][j][l]:
                        dp[i][j][l] = val

                # Option 3: use both s[i] and s[j] as a pair
                c = cost(s[i], s[j])
                for l in range(2, length + 1):
                    inner_cost = get_dp(i + 1, j - 1, l - 2)
                    if inner_cost < INF:
                        new_cost = inner_cost + c
                        if new_cost < dp[i][j][l]:
                            dp[i][j][l] = new_cost

                # Option 4: use only one character (s[i] or s[j]) as a single middle element
                # This gives length 1 with cost 0 (since a single char is always a palindrome with 0 cost)
                # But length 1 should already be covered. Let's verify: get_dp(i+1, j, 1) or get_dp(i, j-1, 1) should propagate 0.
                # Yes, because eventually we reach base case where i==j, dp[i][i][1]=0.

        # Find the maximum l such that dp[0][n-1][l] <= k
        result = 0
        for l in range(n, -1, -1):
            if dp[0][n-1][l] <= k:
                result = l
                break

        return result
