from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        mentions = [0] * numberOfUsers
        # offline_until[u] stores the timestamp when user u becomes online again.
        # Initialized to 0, implying all users are online initially (since timestamps >= 1).
        offline_until = [0] * numberOfUsers

        # Sort events to process in chronological order.
        # If timestamps are equal, OFFLINE events must be processed before MESSAGE events
        # because status changes happen before message handling at the same timestamp.
        # We use a priority: OFFLINE (0) < MESSAGE (1).
        sorted_events = sorted(events, key=lambda e: (int(e[1]), 0 if e[0] == "OFFLINE" else 1))

        for event in sorted_events:
            event_type = event[0]
            timestamp = int(event[1])
            payload = event[2]

            if event_type == "OFFLINE":
                user_id = int(payload)
                # User goes offline at `timestamp` and automatically comes back online at `timestamp + 60`.
                offline_until[user_id] = timestamp + 60

            elif event_type == "MESSAGE":
                # Parse tokens from the mentions string
                tokens = payload.split()
                for token in tokens:
                    if not token:
                        continue

                    if token == "ALL":
                        # "ALL" mentions every user, regardless of online status
                        for u in range(numberOfUsers):
                            mentions[u] += 1
                    elif token == "HERE":
                        # "HERE" mentions only currently online users
                        for u in range(numberOfUsers):
                            # User u is online if the current timestamp is >= the time they return online
                            if offline_until[u] <= timestamp:
                                mentions[u] += 1
                    elif token.startswith("id"):
                        # Explicit ID mention, e.g., "id123"
                        # Mention counts even for offline users
                        try:
                            uid = int(token[2:])
                            if 0 <= uid < numberOfUsers:
                                mentions[uid] += 1
                        except ValueError:
                            pass

        return mentions
