import sys
from collections import Counter

def solve():
    # Read all input from standard input efficiently
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
    except StopIteration:
        return

    dice = []
    for _ in range(N):
        try:
            K = int(next(iterator))
            # Build a frequency counter for each die's faces
            dice.append((K, Counter(int(next(iterator)) for _ in range(K))))
        except StopIteration:
            break

    max_prob = 0.0

    # Iterate over all unique pairs of dice (i, j) with i < j
    for i in range(N):
        K_i, cnt_i = dice[i]
        for j in range(i + 1, N):
            K_j, cnt_j = dice[j]

            # Optimization: iterate over the counter with fewer distinct values
            # to minimize dictionary lookups
            if len(cnt_i) < len(cnt_j):
                small, large = cnt_i, cnt_j
            else:
                small, large = cnt_j, cnt_i

            numerator = 0
            for val, c1 in small.items():
                if val in large:
                    numerator += c1 * large[val]

            # Probability of matching = sum(count_i[v] * count_j[v]) / (K_i * K_j)
            prob = numerator / (K_i * K_j)
            if prob > max_prob:
                max_prob = prob

    # Output with sufficient precision to satisfy 10^-8 error tolerance
    print(f"{max_prob:.15f}")

if __name__ == '__main__':
    solve()
