class Solution:
    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i+1] = P[i] + nums[i]

        prev = [-float('inf')] * (n + 1)
        prev[0] = 0

        for j in range(1, k + 1):
            curr = [-float('inf')] * (n + 1)
            max_prev = -float('inf')
            for i in range(1, n + 1):
                if i < j * m:
                    continue
                if i == j * m:
                    max_prev = -float('inf')
                if i - m >= 0:
                    val = prev[i-m] - P[i-m]
                    if val > max_prev:
                        max_prev = val
                curr[i] = max(curr[i-1], max_prev + P[i])
            prev = curr

        return prev[n]
