class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # dp[i][j][c] stores the max length of palindromic subsequence from s[i..j] with cost <= c
        dp = [[[-1] * (k + 1) for _ in range(n)] for _ in range(n)]

        # Base case: single characters always form a palindrome of length 1 with cost 0
        for i in range(n):
            dp[i][i] = [1] * (k + 1)

        s_ords = [ord(c) for c in s]

        # Iterate over substring lengths
        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                diff = abs(s_ords[i] - s_ords[j])
                cost_diff = diff if diff < 13 else 26 - diff

                prev1 = dp[i+1][j]
                prev2 = dp[i][j-1]

                # Handle empty substring between i and j
                if i + 1 >= j - 1:
                    prev_diag = [0] * (k + 1)
                else:
                    prev_diag = dp[i+1][j-1]

                curr = [-1] * (k + 1)
                for c in range(k + 1):
                    # Option 1: Skip either s[i] or s[j]
                    val = prev1[c] if prev1[c] > prev2[c] else prev2[c]

                    # Option 2: Pair s[i] and s[j]
                    if c >= cost_diff and prev_diag[c - cost_diff] != -1:
                        p_val = prev_diag[c - cost_diff] + 2
                        if p_val > val:
                            val = p_val
                    curr[c] = val
                dp[i][j] = curr

        return max(dp[0][n-1])
