class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        total_k = nums.count(k)
        max_freq = total_k

        unique_vals = set(nums)
        if k in unique_vals:
            unique_vals.remove(k)

        for v in unique_vals:
            curr = 0
            max_sub = -10**9
            for val in nums:
                if val == v:
                    curr += 1
                elif val == k:
                    curr -= 1

                if curr > max_sub:
                    max_sub = curr
                if curr < 0:
                    curr = 0

            if total_k + max_sub > max_freq:
                max_freq = total_k + max_sub

        return max_freq
