class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort(reverse=True)
        # We need to pick the largest possible values as the contributors (max for odd days, 
        # second max for even days). Each even day requires one larger pizza as waste.
        # This greedy structure results in taking every second pizza from the largest half.
        return sum(pizzas[i] for i in range(0, len(pizzas) // 2, 2))
